const now = new Date();

const ackId =
  "ACK-HDFC-" +
  now.getFullYear() +
  String(now.getMonth()+1).padStart(2,'0') +
  String(now.getDate()).padStart(2,'0') +
  "-" +
  Math.floor(Math.random()*10000)
      .toString()
      .padStart(4,'0');

return [{
  json: {
    ...$json,
    acknowledgement_id: ackId,
    application_status: 'Missing Fields Pending'
  }
}];

